"""Writes ../python_codecs.go: run with the reference CPython 3.13.16 (python -I gen_python_codecs.py > ../python_codecs.go; gofmt -w)."""
import codecs, encodings, pkgutil, encodings.aliases as a
names = {}
mods = [m.name for m in pkgutil.iter_modules(encodings.__path__)]
for key in list(a.aliases) + mods:
    if key in ('aliases',) or key.startswith('_'):
        continue
    try:
        info = codecs.lookup(key)
    except LookupError:
        continue
    if not getattr(info, '_is_text_encoding', True):
        continue
    try:
        b'x'.decode(key)
    except LookupError:
        continue
    except Exception:
        pass
    names[key] = info.name
print('// Code generated by testdata/gen_python_codecs.py from the CPython 3.13.16 encodings package; DO NOT EDIT.')
print('package smtpsend')
print()
print('// pythonTextCodecs maps a normalized codec name (encodings.normalize_encoding of the lowered')
print('// name, or an alias key) to codecs.lookup(name).name for the text encodings bytes.decode accepts.')
print('var pythonTextCodecs = map[string]string{')
for k in sorted(names):
    print(f'\t{k!r}: {names[k]!r},'.replace("'", '"'))
print('}')
